  28: /** Multi-factor authentication state machine with bounded retries and lockout. */
  29: public final class AuthenticationPipeline {
  30:     public enum Factor {
  31:         PIN,
  32:         DEVICE_KEY,
  33:         BIOMETRIC,
  34:         COMPANION_APPROVAL,
  35:         VEHICLE_KEY,
  36:         PROVIDER_TOKEN
  37:     }
  38: 
  39:     public enum State {
  40:         CREATED,
  41:         CHALLENGE_PENDING,
  42:         FACTOR_ACCEPTED,
  43:         AUTHENTICATED,
  44:         REJECTED,
  45:         LOCKED,
  46:         EXPIRED,
  47:         CANCELLED
  48:     }
  49: 
  50:     public interface Verifier {
  51:         Verification verify(String accountId, Factor factor, String response, long now);
  52:     }
  53: 
  54:     public static final class Verification {
  55:         public final boolean accepted;
  56:         public final String code;
  57:         public final int assurance;
  58: 
  59:         private Verification(boolean accepted, String code, int assurance) {
  60:             this.accepted = accepted;
  61:             this.code = code;
  62:             this.assurance = assurance;
  63:         }
  64: 
  65:         public static Verification accepted(int assurance) {
  66:             if (assurance < 0 || assurance > 100) {
  67:                 throw new IllegalArgumentException("assurance out of range");
  68:             }
  69:             return new Verification(true, "", assurance);
  70:         }
  71: 
  72:         public static Verification rejected(String code) {
  73:             return new Verification(false, require(code, "code"), 0);
  74:         }
  75:     }
  76: 
  77:     public static final class Policy {
  78:         public final String id;
  79:         public final Set<Factor> allowedFactors;
  80:         public final int requiredFactors;
  81:         public final int minimumAssurance;
  82:         public final int maximumFailures;
  83:         public final long attemptLifetimeMillis;
  84:         public final long lockoutMillis;
  85: 
  86:         public Policy(
  87:                 String id,
  88:                 Collection<Factor> allowedFactors,
  89:                 int requiredFactors,
  90:                 int minimumAssurance,
  91:                 int maximumFailures,
  92:                 long attemptLifetimeMillis,
  93:                 long lockoutMillis) {
  94:             this.id = require(id, "id");
  95:             this.allowedFactors = Collections.unmodifiableSet(
  96:                     EnumSet.copyOf(Objects.requireNonNull(allowedFactors, "allowedFactors")));
  97:             this.requiredFactors = requiredFactors;
  98:             this.minimumAssurance = minimumAssurance;
  99:             this.maximumFailures = maximumFailures;
 100:             this.attemptLifetimeMillis = attemptLifetimeMillis;
 101:             this.lockoutMillis = lockoutMillis;
 102:             if (this.allowedFactors.isEmpty()) {
 103:                 throw new IllegalArgumentException("authentication policy needs factors");
 104:             }
 105:             if (requiredFactors <= 0 || requiredFactors > this.allowedFactors.size()) {
 106:                 throw new IllegalArgumentException("invalid required factor count");
 107:             }
 108:             if (minimumAssurance < 0 || minimumAssurance > 100) {
 109:                 throw new IllegalArgumentException("minimum assurance out of range");
 110:             }
 111:             if (maximumFailures <= 0 || attemptLifetimeMillis <= 0 || lockoutMillis <= 0) {
 112:                 throw new IllegalArgumentException("authentication limits must be positive");
 113:             }
 114:         }
 115:     }
 116: 
 117:     public static final class FactorResult {
 118:         public final Factor factor;
 119:         public final int assurance;
 120:         public final long acceptedAt;
 121: 
 122:         FactorResult(Factor factor, int assurance, long acceptedAt) {
 123:             this.factor = factor;
 124:             this.assurance = assurance;
 125:             this.acceptedAt = acceptedAt;
 126:         }
 127:     }
 128: 
 129:     public static final class Attempt {
 130:         public final String id;
 131:         public final String accountId;
 132:         public final Policy policy;
 133:         public final long createdAt;
 134:         public final long expiresAt;
 135:         private final Map<Factor, FactorResult> accepted = new LinkedHashMap<>();
 136:         private State state = State.CREATED;
 137:         private Factor pendingFactor;
 138:         private int failures;
 139:         private int assurance;
 140:         private String errorCode = "";
 141: 
 142:         Attempt(String id, String accountId, Policy policy, long now) {
 143:             this.id = require(id, "id");
 144:             this.accountId = require(accountId, "accountId");
 145:             this.policy = Objects.requireNonNull(policy, "policy");
 146:             this.createdAt = now;
 147:             this.expiresAt = now + policy.attemptLifetimeMillis;
 148:         }
 149: 
 150:         public synchronized State state() {
 151:             return state;
 152:         }
 153: 
 154:         public synchronized int failures() {
 155:             return failures;
 156:         }
 157: 
 158:         public synchronized int assurance() {
 159:             return assurance;
 160:         }
 161: 
 162:         public synchronized String errorCode() {
 163:             return errorCode;
 164:         }
 165: 
 166:         public synchronized List<FactorResult> acceptedFactors() {
 167:             return Collections.unmodifiableList(new ArrayList<>(accepted.values()));
 168:         }
 169:     }
 170: 
 171:     private final Verifier verifier;
 172:     private final Map<String, Attempt> attempts = new LinkedHashMap<>();
 173:     private final Map<String, Long> lockedUntil = new LinkedHashMap<>();
 174: 
 175:     public AuthenticationPipeline(Verifier verifier) {
 176:         this.verifier = Objects.requireNonNull(verifier, "verifier");
 177:     }
 178: 
 179:     public synchronized Attempt begin(
 180:             String attemptId,
 181:             String accountId,
 182:             Policy policy,
 183:             long now) {
 184:         if (attempts.containsKey(attemptId)) {
 185:             throw new IllegalArgumentException("duplicate attempt: " + attemptId);
 186:         }
 187:         if (lockedUntil.getOrDefault(accountId, 0L) > now) {
 188:             throw new IllegalStateException("account authentication is locked");
 189:         }
 190:         Attempt attempt = new Attempt(attemptId, accountId, policy, now);
 191:         attempts.put(attemptId, attempt);
 192:         return attempt;
 193:     }
 194: 
 195:     public synchronized void requestFactor(String attemptId, Factor factor, long now) {
 196:         Attempt attempt = requireOpen(attemptId, now);
 197:         if (!attempt.policy.allowedFactors.contains(factor)) {
 198:             throw new IllegalArgumentException("factor not allowed: " + factor);
 199:         }
 200:         if (attempt.accepted.containsKey(factor)) {
 201:             throw new IllegalStateException("factor already accepted: " + factor);
 202:         }
 203:         attempt.pendingFactor = factor;
 204:         attempt.state = State.CHALLENGE_PENDING;
 205:         attempt.errorCode = "";
 206:     }
 207: 
 208:     public synchronized Verification submit(String attemptId, String response, long now) {
 209:         Attempt attempt = requireOpen(attemptId, now);
 210:         if (attempt.state != State.CHALLENGE_PENDING || attempt.pendingFactor == null) {
 211:             throw new IllegalStateException("no authentication challenge is pending");
 212:         }
 213:         Factor factor = attempt.pendingFactor;
 214:         Verification verification = verifier.verify(
 215:                 attempt.accountId,
 216:                 factor,
 217:                 Objects.requireNonNull(response, "response"),
 218:                 now);
 219:         attempt.pendingFactor = null;
 220:         if (!verification.accepted) {
 221:             attempt.failures++;
 222:             attempt.errorCode = verification.code;
 223:             if (attempt.failures >= attempt.policy.maximumFailures) {
 224:                 attempt.state = State.LOCKED;
 225:                 lockedUntil.put(
 226:                         attempt.accountId,
