  19: import static org.junit.Assert.assertFalse;
  20: import static org.junit.Assert.assertTrue;
  21: 
  22: import com.cockpitbench.idhub.core.AuthenticationPipeline;
  23: import java.util.Arrays;
  24: import org.junit.Test;
  25: 
  26: public final class AuthenticationPipelineTest {
  27:     @Test
  28:     public void twoAcceptedFactorsReachRequiredAssurance() {
  29:         AuthenticationPipeline pipeline = pipeline();
  30:         AuthenticationPipeline.Attempt attempt = pipeline.begin(
  31:                 "attempt-1",
  32:                 "account-1",
  33:                 policy(),
  34:                 0);
  35:         pipeline.requestFactor("attempt-1", AuthenticationPipeline.Factor.PIN, 1);
  36:         AuthenticationPipeline.Verification pin = pipeline.submit("attempt-1", "accept", 2);
  37:         assertTrue(pin.accepted);
  38:         assertEquals(AuthenticationPipeline.State.FACTOR_ACCEPTED, attempt.state());
  39: 
  40:         pipeline.requestFactor("attempt-1", AuthenticationPipeline.Factor.DEVICE_KEY, 3);
  41:         AuthenticationPipeline.Verification device = pipeline.submit(
  42:                 "attempt-1",
  43:                 "accept",
  44:                 4);
  45: 
  46:         assertTrue(device.accepted);
  47:         assertEquals(AuthenticationPipeline.State.AUTHENTICATED, attempt.state());
  48:         assertEquals(80, attempt.assurance());
  49:         assertEquals(2, attempt.acceptedFactors().size());
  50:     }
  51: 
  52:     @Test
  53:     public void repeatedRejectionsLockAccount() {
  54:         AuthenticationPipeline pipeline = pipeline();
  55:         AuthenticationPipeline.Attempt attempt = pipeline.begin(
  56:                 "attempt-2",
  57:                 "account-2",
  58:                 policy(),
  59:                 0);
  60:         for (int failure = 0; failure < 3; failure++) {
  61:             pipeline.requestFactor("attempt-2", AuthenticationPipeline.Factor.PIN, failure + 1);
  62:             AuthenticationPipeline.Verification result = pipeline.submit(
  63:                     "attempt-2",
  64:                     "reject",
  65:                     failure + 2);
  66:             assertFalse(result.accepted);
  67:         }
  68: 
  69:         assertEquals(AuthenticationPipeline.State.LOCKED, attempt.state());
  70:         assertEquals(3, attempt.failures());
  71:         assertEquals("INVALID_FACTOR", attempt.errorCode());
  72:     }
  73: 
  74:     @Test(expected = IllegalStateException.class)
  75:     public void lockedAccountCannotStartAnotherAttempt() {
  76:         AuthenticationPipeline pipeline = pipeline();
  77:         pipeline.begin("attempt-3", "account-3", policy(), 0);
  78:         for (int failure = 0; failure < 3; failure++) {
  79:             pipeline.requestFactor("attempt-3", AuthenticationPipeline.Factor.PIN, failure + 1);
  80:             pipeline.submit("attempt-3", "reject", failure + 2);
  81:         }
  82:         pipeline.begin("attempt-4", "account-3", policy(), 10);
  83:     }
  84: 
  85:     @Test
  86:     public void outstandingAttemptExpiresDeterministically() {
  87:         AuthenticationPipeline pipeline = pipeline();
  88:         AuthenticationPipeline.Attempt attempt = pipeline.begin(
  89:                 "attempt-5",
  90:                 "account-5",
  91:                 policy(),
  92:                 0);
  93: 
  94:         assertEquals(1, pipeline.expire(100));
  95:         assertEquals(AuthenticationPipeline.State.EXPIRED, attempt.state());
  96:         assertEquals("ATTEMPT_EXPIRED", attempt.errorCode());
  97:     }
  98: 
  99:     private static AuthenticationPipeline pipeline() {
 100:         return new AuthenticationPipeline((account, factor, response, now) ->
 101:                 response.equals("accept")
 102:                         ? AuthenticationPipeline.Verification.accepted(40)
 103:                         : AuthenticationPipeline.Verification.rejected("INVALID_FACTOR"));
 104:     }
 105: 
 106:     private static AuthenticationPipeline.Policy policy() {
 107:         return new AuthenticationPipeline.Policy(
 108:                 "driver-sign-in",
 109:                 Arrays.asList(
 110:                         AuthenticationPipeline.Factor.PIN,
 111:                         AuthenticationPipeline.Factor.DEVICE_KEY,
 112:                         AuthenticationPipeline.Factor.BIOMETRIC),
 113:                 2,
 114:                 70,
 115:                 3,
 116:                 100,
 117:                 1_000);
 118:     }
 119: }
