identity-platform\src\main\java\com\cockpitbench\idhub\platform\IdentityCallbackRegistry.java:16:package com.cockpitbench.idhub.platform; import android.os.RemoteCallbackList; import android.os.RemoteException; import com.cockpitbench.idhub.api.IIdentityListener; public final class IdentityCallbackRegistry { private final RemoteCallbackList<IIdentityListener> callbacks=new RemoteCallbackList<>(); public void add(IIdentityListener value){callbacks.register(value);} public void remove(IIdentityListener value){callbacks.unregister(value);} public void publish(String account,int change){int count=callbacks.beginBroadcast();try{for(int i=0;i<count;i++)try{callbacks.getBroadcastItem(i).onIdentityChanged(account,change);}catch(RemoteException ignored){}}finally{callbacks.finishBroadcast();}} public void close(){callbacks.kill();} }
